// ---- Settings: edit these ----
const OWNER = 'sudarshan161219';
const REPO = 'lateling-reels';
const REF = 'main';
const GEMINI_MODEL = 'gemini-flash-latest';

// One composition per weekday, Sunday first. Set FORCE_COMPOSITION to always use the same one.
const ROTATION = ['Tips', 'BeforeAfter', 'FeatureDemo', 'Trust', 'FeatureDemo', 'BeforeAfter', 'FeatureDemo'];
const FORCE_COMPOSITION = ''; // 'BeforeAfter' | 'FeatureDemo' | 'Tips' | 'Trust' | ''

// For FeatureDemo, the feature changes with the week of the year.
const FEATURES = ['needs-attention', 'find-order', 'order-detail', 'reply-template', 'gmail-panel'];

// Optional angle for the script, for example 'guest checkouts'. Leave empty to let the model choose.
const TOPIC = '';
// ---- End of settings ----

const now = new Date();
const composition = FORCE_COMPOSITION || ROTATION[now.getDay()];
const week = Math.floor((now - new Date(now.getFullYear(), 0, 1)) / (7 * 24 * 3600 * 1000));
const feature = composition === 'FeatureDemo' ? FEATURES[(week + now.getDay()) % FEATURES.length] : '';

// Used as the release tag: reel-<requestId>. Must be unique for every run.
const pad = (n) => String(n).padStart(2, '0');
const requestId =
  `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}-` +
  `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;

return [{json: {owner: OWNER, repo: REPO, ref: REF, model: GEMINI_MODEL, composition, feature, topic: TOPIC, requestId}}];

// Builds the Gemini request: the prompt file from the repo is the system instruction.
const cfg = $('Config').first().json;
const prompt = $json.data;
if (typeof prompt !== 'string' || prompt.length < 1000) {
  throw new Error('Could not load prompts/script-writer.md from the repository.');
}

const lines = [`composition: ${cfg.composition}`];
if (cfg.feature) lines.push(`feature: ${cfg.feature}`);
if (cfg.topic) lines.push(`topic: ${cfg.topic}`);
lines.push(`today: ${new Date().toISOString().slice(0, 10)}`);

return [{json: {payload: {
  system_instruction: {parts: [{text: prompt}]},
  contents: [{role: 'user', parts: [{text: lines.join('\n')}]}],
  generationConfig: {responseMimeType: 'application/json', temperature: 0.9},
}}}];

// Reads the props JSON out of Gemini's answer and does a few cheap checks.
// The full schema check happens in the render itself.
const cfg = $('Config').first().json;
const parts = $json.candidates?.[0]?.content?.parts ?? [];
let text = parts.map((p) => p.text ?? '').join('').trim();
if (!text) throw new Error('Gemini returned no text. Finish reason: ' + ($json.candidates?.[0]?.finishReason ?? 'unknown'));
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

let props;
try {
  props = JSON.parse(text);
} catch (e) {
  throw new Error('Gemini did not return valid JSON: ' + e.message);
}
if (!props || typeof props !== 'object' || Array.isArray(props)) throw new Error('Props must be a JSON object.');
if (typeof props.hook !== 'string') throw new Error('Props have no "hook".');

// House style: no em or en dashes anywhere in the on-screen text.
const dashes = JSON.stringify(props).match(/[–—]/g);
if (dashes) throw new Error('Script contains em or en dashes. Run again.');

// Keep the requested feature, and never let the model choose audio files.
if (cfg.composition === 'FeatureDemo' && cfg.feature) props.feature = cfg.feature;
delete props.audio;

// The post text is for the posting nodes, not for the video, so it is taken out of the props.
const post = props.post && typeof props.post === 'object' ? props.post : {};
delete props.post;
let caption = typeof post.caption === 'string' ? post.caption.trim() : '';
if (!caption) caption = props.hook;
const tags = (Array.isArray(post.hashtags) ? post.hashtags : [])
  .filter((t) => typeof t === 'string')
  .map((t) => '#' + t.replace(/[^\p{L}\p{N}_]/gu, ''))
  .filter((t) => t.length > 1);
const hashtags = [...new Set(tags)].slice(0, 8);
const postText = hashtags.length ? `${caption}\n\n${hashtags.join(' ')}` : caption;
// For X: as many hashtags as fit in 280 characters.
let postTextShort = caption.slice(0, 280);
for (const tag of hashtags) {
  const sep = postTextShort === caption.slice(0, 280) ? '\n\n' : ' ';
  if ((postTextShort + sep + tag).length > 280) break;
  postTextShort += sep + tag;
}

const propsString = JSON.stringify(props);
if (propsString.length > 60000) throw new Error('Props are too long for a workflow input.');

return [{json: {composition: cfg.composition, requestId: cfg.requestId, hook: props.hook, caption, hashtags, postText, postTextShort, props, propsString}}];

// Output of the workflow. Connect your posting nodes after this one.
const job = $('Parse props').first().json;
const cfg = $('Config').first().json;
const release = $json.body;
const asset = (release.assets ?? []).find((a) => a.name.endsWith('.mp4'));
if (!asset) throw new Error('The release exists but has no MP4 attached.');

return [{json: {
  videoUrl: asset.browser_download_url,
  fileName: asset.name,
  sizeBytes: asset.size,
  composition: job.composition,
  feature: cfg.feature,
  hook: job.hook,
  caption: job.caption,
  hashtags: job.hashtags,
  postText: job.postText,
  postTextShort: job.postTextShort,
  requestId: job.requestId,
  releaseTag: release.tag_name,
  releasePage: release.html_url,
  props: job.props,
}}];
